CREATE TABLE ${primehrSchema}.succession_development_plan (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, series_id VARCHAR(36) NOT NULL, plan_version INT NOT NULL, supersedes_plan_id VARCHAR(36), pool_decision_id VARCHAR(36) NOT NULL, assessment_id VARCHAR(36) NOT NULL, candidate_id VARCHAR(36) NOT NULL, employee_no VARCHAR(100) NOT NULL, employee_name VARCHAR(300) NOT NULL, target_position_name VARCHAR(250) NOT NULL, readiness_level_code VARCHAR(80) NOT NULL, overall_goal VARCHAR(4000) NOT NULL, starts_on DATE NOT NULL, target_completion_date DATE NOT NULL, next_review_on DATE NOT NULL, status VARCHAR(20) NOT NULL, acknowledgment_status VARCHAR(30) NOT NULL, acknowledgment_response VARCHAR(4000), acknowledged_at DATETIMEOFFSET, activated_by VARCHAR(100), activated_at DATETIMEOFFSET, completed_by VARCHAR(100), completed_at DATETIMEOFFSET, record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at DATETIMEOFFSET NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT uk_succ_dev_plan_decision UNIQUE(agency_id,pool_decision_id), CONSTRAINT uk_succ_dev_plan_series_version UNIQUE(agency_id,series_id,plan_version), CONSTRAINT fk_succ_dev_plan_previous FOREIGN KEY(supersedes_plan_id) REFERENCES ${primehrSchema}.succession_development_plan(id), CONSTRAINT fk_succ_dev_plan_decision FOREIGN KEY(pool_decision_id) REFERENCES ${primehrSchema}.succession_pool_decision(id), CONSTRAINT fk_succ_dev_plan_assessment FOREIGN KEY(assessment_id) REFERENCES ${primehrSchema}.succession_readiness_assessment(id), CONSTRAINT fk_succ_dev_plan_candidate FOREIGN KEY(candidate_id) REFERENCES ${primehrSchema}.succession_candidate(id), CONSTRAINT ck_succ_dev_plan_version CHECK(plan_version>=1), CONSTRAINT ck_succ_dev_plan_dates CHECK(target_completion_date>=starts_on AND next_review_on>=starts_on AND next_review_on<=target_completion_date), CONSTRAINT ck_succ_dev_plan_status CHECK(status IN('DRAFT','ACTIVE','COMPLETED','SUPERSEDED','CANCELLED')), CONSTRAINT ck_succ_dev_plan_ack CHECK(acknowledgment_status IN('PENDING','ACKNOWLEDGED','RESPONSE_SUBMITTED'))
);
CREATE INDEX ix_succ_dev_plan_employee ON ${primehrSchema}.succession_development_plan(agency_id,employee_no,status);

CREATE TABLE ${primehrSchema}.succession_development_source (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, plan_id VARCHAR(36) NOT NULL, source_type VARCHAR(30) NOT NULL, source_id VARCHAR(36) NOT NULL, source_parent_id VARCHAR(36), source_version BIGINT NOT NULL, source_fingerprint VARCHAR(120) NOT NULL, source_summary VARCHAR(2000) NOT NULL, source_date DATE, record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at DATETIMEOFFSET NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT uk_succ_dev_source UNIQUE(agency_id,plan_id,source_type,source_id), CONSTRAINT fk_succ_dev_source_plan FOREIGN KEY(plan_id) REFERENCES ${primehrSchema}.succession_development_plan(id), CONSTRAINT ck_succ_dev_source_type CHECK(source_type IN('APPROVED_IDP_ITEM','COMPLETED_LD_CASE')), CONSTRAINT ck_succ_dev_source_version CHECK(source_version>=0)
);
CREATE INDEX ix_succ_dev_source_plan ON ${primehrSchema}.succession_development_source(agency_id,plan_id,source_type);

CREATE TABLE ${primehrSchema}.succession_development_milestone (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, plan_id VARCHAR(36) NOT NULL, title VARCHAR(250) NOT NULL, measurable_outcome VARCHAR(3000) NOT NULL, due_date DATE NOT NULL, display_order INT NOT NULL, status VARCHAR(20) NOT NULL, evidence_reference VARCHAR(1000), employee_visible_feedback VARCHAR(3000), restricted_feedback VARCHAR(3000), updated_by_actor VARCHAR(100), status_updated_at DATETIMEOFFSET, record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at DATETIMEOFFSET NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT uk_succ_dev_milestone_order UNIQUE(agency_id,plan_id,display_order), CONSTRAINT fk_succ_dev_milestone_plan FOREIGN KEY(plan_id) REFERENCES ${primehrSchema}.succession_development_plan(id), CONSTRAINT ck_succ_dev_milestone_order CHECK(display_order>=1), CONSTRAINT ck_succ_dev_milestone_status CHECK(status IN('PLANNED','IN_PROGRESS','COMPLETED','NOT_MET'))
);
CREATE INDEX ix_succ_dev_milestone_plan ON ${primehrSchema}.succession_development_milestone(agency_id,plan_id,display_order);

CREATE TABLE ${primehrSchema}.succession_development_review (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, plan_id VARCHAR(36) NOT NULL, review_sequence INT NOT NULL, review_date DATE NOT NULL, recommendation VARCHAR(30) NOT NULL, employee_visible_summary VARCHAR(4000) NOT NULL, restricted_rationale VARCHAR(4000) NOT NULL, reviewed_by VARCHAR(100) NOT NULL, reviewed_at DATETIMEOFFSET NOT NULL, next_review_on DATE, record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at DATETIMEOFFSET NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT uk_succ_dev_review_sequence UNIQUE(agency_id,plan_id,review_sequence), CONSTRAINT fk_succ_dev_review_plan FOREIGN KEY(plan_id) REFERENCES ${primehrSchema}.succession_development_plan(id), CONSTRAINT ck_succ_dev_review_sequence CHECK(review_sequence>=1), CONSTRAINT ck_succ_dev_review_recommendation CHECK(recommendation IN('CONTINUE','COMPLETE','REMOVE_FROM_POOL'))
);
CREATE INDEX ix_succ_dev_review_plan ON ${primehrSchema}.succession_development_review(agency_id,plan_id,review_sequence);

CREATE TABLE ${primehrSchema}.succession_pool_membership_event (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, pool_decision_id VARCHAR(36) NOT NULL, candidate_id VARCHAR(36) NOT NULL, previous_event_id VARCHAR(36), event_sequence INT NOT NULL, event_type VARCHAR(20) NOT NULL, resulting_status VARCHAR(20) NOT NULL, effective_on DATE NOT NULL, expires_on DATE, employee_visible_reason VARCHAR(4000) NOT NULL, restricted_rationale VARCHAR(4000) NOT NULL, recorded_by VARCHAR(100) NOT NULL, recorded_at DATETIMEOFFSET NOT NULL, record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at DATETIMEOFFSET NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT uk_succ_membership_event_sequence UNIQUE(agency_id,pool_decision_id,event_sequence), CONSTRAINT fk_succ_membership_decision FOREIGN KEY(pool_decision_id) REFERENCES ${primehrSchema}.succession_pool_decision(id), CONSTRAINT fk_succ_membership_candidate FOREIGN KEY(candidate_id) REFERENCES ${primehrSchema}.succession_candidate(id), CONSTRAINT fk_succ_membership_previous FOREIGN KEY(previous_event_id) REFERENCES ${primehrSchema}.succession_pool_membership_event(id), CONSTRAINT ck_succ_membership_sequence CHECK(event_sequence>=1), CONSTRAINT ck_succ_membership_event_type CHECK(event_type IN('ACTIVATED','CORRECTED','EXPIRED','REMOVED','REINSTATED')), CONSTRAINT ck_succ_membership_status CHECK(resulting_status IN('ACTIVE','EXPIRED','REMOVED'))
);
CREATE INDEX ix_succ_membership_current ON ${primehrSchema}.succession_pool_membership_event(agency_id,pool_decision_id,event_sequence);
